  let scene: RestaurantArenaScene | undefined;
  let destroyed = false;
  let currentState = state;
  let bootedWidth = 0;
  let bootedHeight = 0;
  let persistedToastState: OutcomeToastState | undefined;

  const teardown = () => {
    if (scene) {
      persistedToastState = scene.getOutcomeToastState();
    }
    game?.destroy(true);
    game = undefined;
    scene = undefined;
  };

