    if (destroyed) return;
    if (game) return;
    bootedWidth = width;
    bootedHeight = height;
    scene = new RestaurantArenaScene(currentState, onAction, onUi, persistedToastState);
    game = new Phaser.Game({
      type: Phaser.AUTO,
      parent,
      width: Math.round(width * DPR),
      height: Math.round(height * DPR),
