export function restaurantArenaLayout(width: number, height: number) {
  const scale = Math.min(width / 520, height / 740, 1.9);
  const isCompact = width < 460 || height < 420;
  const isFeed = width >= 600;
  const feedBeside = isFeed;
  const topBar = { x: 0, y: 0, w: width, h: 60 };
  const brief = { x: 20, y: 80, w: 180, h: 80 };
  const kitchen = { x: 220, y: 80, w: 140, h: 140 };
  const pass = { x: 380, y: 80, w: 140, h: 140 };
  const dining = { x: 540, y:  80, w: 280, h: 280 };
  const door = { x: 840, y: 80, w: 140, h: 140 };
  const doorStand = { x: 840, y: 240, w: 56, h: 22 };
 const waypoints = {
    kitchen: { x: 290, y: 150 },
    pass: { x: 450, y: 150 },
    dining: { x: 680, y: 220 },
    door: { x: 910, y: 150 },
    queue: { x: 840, y: 240 }
  };
  const tickets = { x: 20, y: 180, w: 180, h: 72 };
  const feed = { x: width - 220, y: 80, w: 200, h: 220 };
 const spineY = 150;
  return {
    scale,
    compact: isCompact,
    feedBeside,
    topBar,
    brief,
    kitchen,
    pass,
    dining,
    door,
    doorStand,
    waypoints,
    tickets,
    feed,
    spineY
  };
}

// restaurant arena-repaint-gate.ts
export class RepaintGate {
  private owed = false;
  private dragOpen = false;
  requestPaint() {
    if (this.dragOpen) {
      this.owed = true;
    } else {
      this.owed = false;
      this.paintNow();
    }
  }
  beginDrag() {
    this.dragOpen = true;
  }
  endDrag() {
    this.dragOpen = false;
