export const WALK_GRAPH = {
  kitchen: ['pass', 'floor'],
  pass: ['kitchen', 'floor', 'dining'],
  floor: ['kitchen', 'pass', 'dining', 'queue'],
  dining: ['pass', 'floor', 'door'],
  door: ['dining', 'queue'],
  queue: ['floor', 'door']
};

export function bfsPath(from: string, to: string) {
  const graph = WALK_GRAPH;
  const queue: string[] = [];
  const cameFrom = new Map<string, string>();
  const visited = new Set<string>();
  queue.push(from);
  visited.add(from);
  while (queue.length) {
    const curr = queue.shift()!;
    if (curr === to) break;
    for (const next of graph[curr]) {
      if (!visited.has(next)) {
        visited.add(next);
        cameFrom.set(next, curr);
        queue.push(next);
      }
    }
  }
  const path: string[] = [];
  let cur = to;
  while (cur) {
    path.push(cur);
    cur = cameFrom.get(cur)!;
  }
  return path.reverse();
}

export function corridorPoints(start: {x: number, y: number}, nodes: string[], waypoints: Record<string, {x: number, y: number}>, spineY: number) {
  const points: {x: number, y: number}[] = [];
  let x = start.x;
  let y = start.y;
  const push = (nx: number, ny: number) => {
    if (points.length === 0 && nx === start.x && ny === start.y) return;
    if (points.length >  0 && points[points.length - 1].x === nx && points[points.length - 1].y === ny) return;
    points.push({ x: nx, y: ny });
    x = nx;
    y = ny;
  };
  for (let i = 0; i < nodes.length; i++) {
    const dest = waypoints[nodes[i]];
    if (y !== spineY) push(x, spineY);
    if (x !== dest.x) push(dest.x, spineY);
    if (i === nodes.length - 1) {
      push(dest.x, dest.y);
 }
  }
  return points;
}

