export type ArenaRect = { x: number; y: number; width: number; height: number };
export type ArenaPoint = { x: number; y: number };
export type ArenaLocation = "floor" | "kitchen" | "pass" | "queue";

export interface RestaurantArenaLayout {
  compact: boolean;
  scale: number;
  feedBeside: boolean;
  topBar: ArenaRect;
  brief: ArenaRect;
  kitchen: ArenaRect;
  pass: ArenaRect;
  dining: ArenaRect;
  door: ArenaRect;
  doorStand: ArenaRect;
  waypoints: Record<ArenaLocation, ArenaPoint>;
  /** Y coordinate of the hallway line that runs through the pass zone. */
  spineY: number;
  tickets: ArenaRect;
  feed: ArenaRect;
}

const BASELINE_WIDTH = 520;
const BASELINE_HEIGHT = 740;
const COMPACT_WIDTH = 460;
const COMPACT_HEIGHT = 420;
const FEED_BESIDE_WIDTH = 600;
const SCALE_CAP = 1.9;
const DOOR_STAND_MIN_WIDTH = 56;
const DOOR_STAND_MIN_HEIGHT = 22;

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function rect(x: number, y: number, width: number, height: number): ArenaRect {
  return { x, y, width: Math.max(0, width), height: Math.max(0, height) };
}

function center(zone: ArenaRect): ArenaPoint {
