import type { ArenaLocation, ArenaPoint } from "./restaurant-arena-layout.js";

export type WalkNode = ArenaLocation;
export type Point = ArenaPoint;

export const WALK_GRAPH: Record<WalkNode, readonly WalkNode[]> = {
  kitchen: ["pass"],
  pass: ["kitchen", "floor"],
  floor: ["pass", "queue"],
  queue: ["floor"],
};

export const WALK_SPEED_PX_PER_SEC = 200;

const NODES: readonly WalkNode[] = ["kitchen", "pass", "floor", "queue"];

export function bfsPath(from: WalkNode, to: WalkNode): WalkNode[] {
  if (from === to) return [from];
  const queue: WalkNode[] = [from];
  const prev = new Map<WalkNode, WalkNode | null>([[from, null]]);
  while (queue.length > 0) {
    const cur = queue.shift()!;
    for (const next of WALK_GRAPH[cur]) {
      if (prev.has(next)) continue;
      prev.set(next, cur);
      if (next === to) {
        const path: WalkNode[] = [to];
        let node: WalkNode | null = cur;
        while (node) {
          path.push(node);
          node = prev.get(node) ?? null;
        }
        path.reverse();
        return path;
      }
      queue.push(next);
    }
  }
  return [from];
}

function samePoint(a: Point, b: Point): boolean {
  return a.x === b.x && a.y === b.y;
}

function pushUnique(points: Point[], point: Point): void {
  const last = points[points.length - 1];
  if (last && samePoint(last, point)) return;
  points.push(point);
}

/**
 * Pixel path from `start`, through `nodes` in order, riding the y=`spineY`
 * hallway instead of cutting diagonally through a room.
 *
 * Through-stations stay on the hallway; only the final node peels off to its
 * resting slot.
 */
export function corridorPoints(
  start: Point,
  nodes: readonly WalkNode[],
  waypoints: Record<WalkNode, Point>,
  spineY: number,
): Point[] {
  const points: Point[] = [];
  let x = start.x;
  let y = start.y;

  const go = (nx: number, ny: number) => {
    if (nx === x && ny === y) return;
    pushUnique(points, { x: nx, y: ny });
    x = nx;
    y = ny;
  };

  for (let i = 0; i < nodes.length; i++) {
    const dest = waypoints[nodes[i]!];
    if (!dest) continue;
    const last = i === nodes.length - 1;
    if (y !== spineY) go(x, spineY);
    if (x !== dest.x) go(dest.x, spineY);
    if (last && (x !== dest.x || y !== dest.y)) go(dest.x, dest.y);
  }
  return points;
}

export function hopDurationMs(from: Point, to: Point): number {
  const dist = Math.hypot(to.x - from.x, to.y - from.y);
  if (dist === 0) return 0;
  return (dist / WALK_SPEED_PX_PER_SEC) * 1000;
}

function easeHop(t: number): number {
  const x = t <= 0 ? 0 : t >= 1 ? 1 : t;
  return x * x * (3 - 2 * x);
}

function closestNode(point: Point, waypoints: Record<WalkNode, Point>): WalkNode {
  let best: WalkNode = "floor";
  let bestDist = Infinity;
  for (const node of NODES) {
    const slot = waypoints[node];
    if (!slot) continue;
    const dist = Math.hypot(point.x - slot.x, point.y - slot.y);
    if (dist < bestDist) {
      bestDist = dist;
      best = node;
    }
  }
  return best;
}

export class StaffWalker {
  x: number;
  y: number;
  facing: 1 | -1 = 1;
  walking = false;
  dragging = false;
  node: WalkNode;

  private hops: Point[] = [];
  private hopIndex = 0;
  private hopElapsed = 0;
  private hopDuration = 0;
  private hopFrom: Point;
  private targetNode: WalkNode;

  constructor(node: WalkNode, slot: Point) {
    this.node = node;
    this.targetNode = node;
    this.x = slot.x;
    this.y = slot.y;
    this.hopFrom = { x: slot.x, y: slot.y };
  }

  snap(slot: Point, node: WalkNode): void {
    this.x = slot.x;
    this.y = slot.y;
    this.node = node;
    this.targetNode = node;
    this.walking = false;
    this.hops = [];
    this.hopIndex = 0;
    this.hopElapsed = 0;
    this.hopDuration = 0;
    this.hopFrom = { x: slot.x, y: slot.y };
  }

  setTarget(target: WalkNode, waypoints: Record<WalkNode, Point>, spineY: number): void {
    this.targetNode = target;
    const fromNode = closestNode({ x: this.x, y: this.y }, waypoints);
    this.node = fromNode;
    const nodes = bfsPath(fromNode, target);
    this.hops = corridorPoints({ x: this.x, y: this.y }, nodes, waypoints, spineY);
    this.hopIndex = 0;
    this.hopElapsed = 0;
    this.hopFrom = { x: this.x, y: this.y };
    const first = this.hops[0];
    if (!first) {
      this.walking = false;
      this.node = target;
      return;
    }
    this.walking = true;
    this.hopDuration = hopDurationMs(this.hopFrom, first);
    this.faceToward(first);
  }

  step(dtMs: number, speed: number): boolean {
    if (this.dragging || !this.walking || speed <= 0) return false;
    const prevX = this.x;
    const prevY = this.y;
    let remaining = dtMs * speed;
    while (remaining > 0 && this.walking) {
      const dest = this.hops[this.hopIndex];
      if (!dest) {
        this.finishWalk();
        break;
      }
      if (this.hopDuration <= 0) {
        this.completeHop(dest);
        continue;
      }
      const left = this.hopDuration - this.hopElapsed;
      if (remaining >= left) {
        remaining -= left;
        this.completeHop(dest);
      } else {
        this.hopElapsed += remaining;
        remaining = 0;
        const t = easeHop(this.hopElapsed / this.hopDuration);
        this.x = this.hopFrom.x + (dest.x - this.hopFrom.x) * t;
        this.y = this.hopFrom.y + (dest.y - this.hopFrom.y) * t;
      }
    }
    return this.x !== prevX || this.y !== prevY;
  }

  private completeHop(dest: Point): void {
    this.x = dest.x;
    this.y = dest.y;
    this.hopFrom = { x: dest.x, y: dest.y };
    this.hopIndex += 1;
    this.hopElapsed = 0;
    const next = this.hops[this.hopIndex];
    if (!next) {
      this.finishWalk();
      return;
    }
    this.hopDuration = hopDurationMs(this.hopFrom, next);
    this.faceToward(next);
  }

  private finishWalk(): void {
    this.walking = false;
    this.node = this.targetNode;
    this.hops = [];
    this.hopIndex = 0;
    this.hopDuration = 0;
    this.hopElapsed = 0;
  }

  private faceToward(dest: Point): void {
    const dx = dest.x - this.x;
    if (dx > 0) this.facing = 1;
    else if (dx < 0) this.facing = -1;
  }
}

export class RepaintGate {
  private dragging = false;
  private owed = false;

  constructor() {}

  get isDragging(): boolean {
    return this.dragging;
  }

  beginDrag(): void {
    this.dragging = true;
  }

  requestPaint(): boolean {
    if (this.dragging) {
      this.owed = true;
      return false;
    }
    return true;
  }

  endDrag(): boolean {
    const owed = this.dragging && this.owed;
    this.dragging = false;
    this.owed = false;
    return owed;
  }

  resize(): void {
    this.dragging = false;
    this.owed = false;
  }
}

