/** A hallway stripe through the pass so walks read as a corridor, not a teleport. */
private drawHallway(g: Phaser.GameObjects.Graphics, layout: RestaurantArenaLayout): void {
  const { kitchen, dining, pass, spineY, compact } = layout;
  const thickness = compact ? 6 : 10;
  const left = kitchen.x;
  const right = dining.x + dining.width;
  g.fillStyle(0x7b4c2e, 0.28);
  g.fillRect(left, spineY - thickness / 2, Math.max(0, right - left), thickness);
  g.fillStyle(0x5c3a22, 0.45);
  g.fillRect(pass.x, spineY - 2, pass.width, 4);
}

