import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout, type ArenaRect, type RestaurantArenaLayout } from "./restaurant-arena-layout.js";

function fits(rect: ArenaRect, width: number, height: number): boolean {
  return rect.x >= 0 && rect.y >= 0 && rect.x + rect.width <= width + 1e-6 && rect.y + rect.height <= height + 1e-6;
}

function inside(point: { x: number; y: number }, rect: ArenaRect): boolean {
  return point.x >= rect.x && point.x <= rect.x + rect.width && point.y >= rect.y && point.y <= rect.y + rect.height;
}

function namedRects(layout: RestaurantArenaLayout): ArenaRect[] {
  return [
    layout.topBar,
    layout.brief,
    layout.kitchen,
    layout.pass,
    layout.dining,
    layout.door,
    layout.tickets,
    layout.feed,
  ];
}

describe("restaurantArenaLayout", () => {
  test("baseline 520x740 is scale 1, not compact, feed stacked", () => {
    const layout = restaurantArenaLayout(520, 740);
    expect(layout.scale).toBe(1);
    expect(layout.compact).toBe(false);
    expect(layout.feedBeside).toBe(false);
    expect(layout.feed.y).toBeGreaterThanOrEqual(layout.tickets.y + layout.tickets.height - 1e-6);
  });

  test("grows with the tighter of width/520 and height/740, capped near 1.9", () => {
    const grown = restaurantArenaLayout(780, 1110);
    expect(grown.compact).toBe(false);
    expect(grown.scale).toBeCloseTo(1.5, 5);

    const capped = restaurantArenaLayout(2000, 2000);
    expect(capped.scale).toBeCloseTo(1.9, 5);
    expect(capped.scale).toBeLessThanOrEqual(1.9);
  });

  test("stays compact and does not grow text below ~460 wide or ~420 tall", () => {
    expect(restaurantArenaLayout(459, 800).compact).toBe(true);
    expect(restaurantArenaLayout(459, 800).scale).toBe(1);
    expect(restaurantArenaLayout(800, 419).compact).toBe(true);
    expect(restaurantArenaLayout(800, 419).scale).toBe(1);
    expect(restaurantArenaLayout(460, 420).compact).toBe(false);
  });

  test("sits the feed beside the floor once the window is roughly 600px+", () => {
    const stacked = restaurantArenaLayout(599, 740);
    expect(stacked.feedBeside).toBe(false);

    const beside = restaurantArenaLayout(600, 740);
    expect(beside.feedBeside).toBe(true);
    expect(beside.feed.x).toBeGreaterThanOrEqual(beside.kitchen.x + beside.kitchen.width);
    expect(beside.feed.y).toBeLessThan(beside.kitchen.y + beside.kitchen.height);
  });

  test("doorStand stays at least 56 by 22 and queue sits on it", () => {
    for (const [w, h] of [
      [320, 240],
      [400, 400],
      [520, 740],
      [600, 740],
      [900, 900],
    ] as const) {
      const layout = restaurantArenaLayout(w, h);
      expect(layout.doorStand.width).toBeGreaterThanOrEqual(56);
      expect(layout.doorStand.height).toBeGreaterThanOrEqual(22);
      expect(inside(layout.waypoints.queue, layout.doorStand)).toBe(true);
      expect(layout.waypoints.queue).toEqual({
        x: layout.doorStand.x + layout.doorStand.width / 2,
        y: layout.doorStand.y + layout.doorStand.height / 2,
      });
    }
  });

  test("hallway line runs through the pass and floor waypoint is the dining slot", () => {
    const layout = restaurantArenaLayout(520, 740);
    expect(layout.spineY).toBeGreaterThanOrEqual(layout.pass.y);
    expect(layout.spineY).toBeLessThanOrEqual(layout.pass.y + layout.pass.height);
    expect(layout.waypoints.pass.y).toBe(layout.spineY);
    expect(inside(layout.waypoints.floor, layout.dining)).toBe(true);
    expect(inside(layout.waypoints.kitchen, layout.kitchen)).toBe(true);
  });

  test("rects fit inside the requested width and height", () => {
    for (const [w, h] of [
      [320, 240],
      [459, 419],
      [520, 740],
      [600, 740],
      [720, 780],
      [1040, 1480],
    ] as const) {
      const layout = restaurantArenaLayout(w, h);
      for (const zone of namedRects(layout)) {
        expect(fits(zone, w, h)).toBe(true);
      }
      expect(layout.doorStand.x).toBeGreaterThanOrEqual(0);
      expect(layout.doorStand.y).toBeGreaterThanOrEqual(0);
      expect(layout.doorStand.x + layout.doorStand.width).toBeLessThanOrEqual(w + 1e-6);
      expect(layout.doorStand.y + layout.doorStand.height).toBeLessThanOrEqual(h + 1e-6);
    }
  });
});

import { describe, expect, test } from "bun:test";
import { restaurantArenaLayout } from "./restaurant-arena-layout.js";
import {
  WALK_GRAPH,
  WALK_SPEED_PX_PER_SEC,
  bfsPath,
  corridorPoints,
  hopDurationMs,
  StaffWalker,
  type Point,
} from "./staff-walk.js";

function axisAligned(a: Point, b: Point): boolean {
  return a.x === b.x || a.y === b.y;
}

describe("staff walk graph", () => {
  test("wires kitchen-pass-floor-queue as one hallway", () => {
    expect([...WALK_GRAPH.kitchen]).toEqual(["pass"]);
    expect([...WALK_GRAPH.pass]).toEqual(["kitchen", "floor"]);
    expect([...WALK_GRAPH.floor]).toEqual(["pass", "queue"]);
    expect([...WALK_GRAPH.queue]).toEqual(["floor"]);
  });

  test("kitchen to queue always routes through pass and floor", () => {
    expect(bfsPath("kitchen", "queue")).toEqual(["kitchen", "pass", "floor", "queue"]);
    expect(bfsPath("queue", "kitchen")).toEqual(["queue", "floor", "pass", "kitchen"]);
    expect(bfsPath("kitchen", "kitchen")).toEqual(["kitchen"]);
  });
});

describe("corridorPoints", () => {
  const layout = restaurantArenaLayout(520, 740);
  const waypoints = layout.waypoints;
  const spineY = layout.spineY;

  test("rides the hallway instead of cutting diagonally across rooms", () => {
    const start = waypoints.kitchen;
    const hops = corridorPoints(start, bfsPath("kitchen", "queue"), waypoints, spineY);
    expect(hops.length).toBeGreaterThan(0);
    expect(hops[hops.length - 1]).toEqual(waypoints.queue);

    let prev = start;
    const spineXs: number[] = [];
    for (const hop of hops) {
      expect(axisAligned(prev, hop)).toBe(true);
      if (hop.y === spineY) spineXs.push(hop.x);
      prev = hop;
    }
    expect(spineXs).toContain(waypoints.pass.x);
    expect(spineXs).toContain(waypoints.floor.x);
  });

  test("through-stations stay on the spine until the last node", () => {
    const hops = corridorPoints(waypoints.kitchen, ["pass", "floor"], waypoints, spineY);
    const last = hops[hops.length - 1];
    expect(last).toEqual(waypoints.floor);
    const passHop = hops.find((hop) => hop.x === waypoints.pass.x);
    expect(passHop?.y).toBe(spineY);
  });
});

describe("hopDurationMs", () => {
  test("is 200px per second", () => {
    expect(WALK_SPEED_PX_PER_SEC).toBe(200);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 200, y: 0 })).toBe(1000);
    expect(hopDurationMs({ x: 0, y: 0 }, { x: 0, y: 100 })).toBe(500);
    expect(hopDurationMs({ x: 3, y: 4 }, { x: 3, y: 4 })).toBe(0);
  });
});

describe("StaffWalker", () => {
  const layout = restaurantArenaLayout(520, 740);
  const waypoints = layout.waypoints;

  test("parks on the slot, snaps, and walks the hallway with easing", () => {
    const walker = new StaffWalker("kitchen", waypoints.kitchen);
    expect(walker.x).toBe(waypoints.kitchen.x);
    expect(walker.y).toBe(waypoints.kitchen.y);
    expect(walker.node).toBe("kitchen");
    expect(walker.walking).toBe(false);
    expect(walker.dragging).toBe(false);
    expect(walker.facing).toBe(1);

    walker.snap(waypoints.pass, "pass");
    expect(walker.x).toBe(waypoints.pass.x);
    expect(walker.y).toBe(waypoints.pass.y);
    expect(walker.node).toBe("pass");
    expect(walker.walking).toBe(false);

    walker.snap(waypoints.kitchen, "kitchen");
    walker.setTarget("queue", waypoints, layout.spineY);
    expect(walker.walking).toBe(true);

    expect(walker.step(16, 0)).toBe(false);
    expect(walker.x).toBe(waypoints.kitchen.x);

    walker.dragging = true;
    expect(walker.step(1000, 1)).toBe(false);
    walker.dragging = false;

    const moved = walker.step(50, 1);
    expect(moved).toBe(true);
    expect(walker.x).not.toBe(waypoints.queue.x);

    walker.step(60_000, 1);
    expect(walker.walking).toBe(false);
    expect(walker.node).toBe("queue");
    expect(walker.x).toBe(waypoints.queue.x);
    expect(walker.y).toBe(waypoints.queue.y);
  });

  test("2x speed hustles and pause freezes", () => {
    const slow = new StaffWalker("kitchen", waypoints.kitchen);
    const fast = new StaffWalker("kitchen", waypoints.kitchen);
    slow.setTarget("pass", waypoints, layout.spineY);
    fast.setTarget("pass", waypoints, layout.spineY);
    slow.step(80, 1);
    fast.step(80, 2);
    const slowDist = Math.hypot(slow.x - waypoints.kitchen.x, slow.y - waypoints.kitchen.y);
    const fastDist = Math.hypot(fast.x - waypoints.kitchen.x, fast.y - waypoints.kitchen.y);
    expect(fastDist).toBeGreaterThan(slowDist);
  });
});

import { describe, expect, test } from "bun:test";
import { RepaintGate } from "./restaurant-arena-repaint-gate.js";

describe("RepaintGate", () => {
  test("paints immediately unless a drag is open", () => {
    const gate = new RepaintGate();
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);

    gate.beginDrag();
    expect(gate.isDragging).toBe(true);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.requestPaint()).toBe(false);
    expect(gate.endDrag()).toBe(true);
    expect(gate.isDragging).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });

  test("endDrag reports a single owed repaint and then is clear", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);

    gate.beginDrag();
    gate.requestPaint();
    gate.requestPaint();
    expect(gate.endDrag()).toBe(true);
    expect(gate.endDrag()).toBe(false);
  });

  test("resize drops any open drag and clears anything owed", () => {
    const gate = new RepaintGate();
    gate.beginDrag();
    gate.requestPaint();
    gate.resize();
    expect(gate.isDragging).toBe(false);
    expect(gate.endDrag()).toBe(false);
    expect(gate.requestPaint()).toBe(true);
  });
});

