I see the issue with the repaint gate logic—calling `resize()` inside `paint()` could clear owed repaints prematurely, and the dragend handling after a resize or scene destroy needs care. Let me refactor the `RepaintGate` to handle this more robustly.

Here's the updated `restaurant-arena-repaint gate.ts`:

```typescript
import { RepaintGate } from './restaurant-arena-repaint-gate';

export class RepaintGate {
  private owed: boolean = false;
  private dragOpen: boolean = false;

  requestPaint() {
    if (this.dragOpen) {
      this.owed = true;
 } else {
      this.owed = false;
      this.paint();
    }
  }

  beginDrag() {
    this.dragOpen = true;
  }

  endDrag() {
    const hadDrag = this.dragOpen;
    this.dragOpen = false;
    if (hadDrag && this.owed) {
 this.owed = false;
      return true;
    }
    return false;
  }

  resize() {
    this.dragOpen = false;
    this.owed = false;
  }

  private paint() {
    // actual paint implementation
  }
}
